//! NS-01: Rust-side consumption of the committed TypeScript parity fixtures.
//!
//! The fixture bundle is generated by the TypeScript scanner (see
//! `src/features/scanner/__tests__/nativeScannerFixtureGenerator.ts`), so Rust can never
//! invent its own expectations. Every numeric case is re-evaluated here and compared
//! against the recorded TypeScript values, and every contract case is replayed through
//! the Rust validator with the same accept/reject decision.

use super::ast::{
    evaluate_rule_latest, minimum_bars_for_expression, parse_native_scan_request_v1, EvalBar,
    ExprV1, PriceBasisV1,
};
use serde::Deserialize;
use serde_json::Value;
use std::collections::BTreeMap;

const FIXTURE_JSON: &str =
    include_str!("../../../src/features/scanner/fixtures/nativeScannerParityFixtures.v1.json");

#[derive(Debug, Deserialize)]
struct FixtureBar {
    date: String,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
    volume: f64,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct NumericCase {
    id: String,
    description: String,
    expression: Value,
    bar_set: String,
    expected_values: Vec<Option<f64>>,
    expected_latest_matched: bool,
    minimum_bars: usize,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ContractCase {
    id: String,
    description: String,
    expect: String,
    payload: Value,
    #[serde(default)]
    expected_issue_codes: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct FixtureBundle {
    contract_version: String,
    schema_version: u32,
    bar_sets: BTreeMap<String, Vec<FixtureBar>>,
    numeric_cases: Vec<NumericCase>,
    contract_cases: Vec<ContractCase>,
}

fn load_bundle() -> FixtureBundle {
    serde_json::from_str(FIXTURE_JSON).expect("native scanner parity fixture bundle must parse")
}

fn pack_date(value: &str) -> u32 {
    value
        .replace('-', "")
        .parse()
        .expect("fixture date YYYY-MM-DD")
}

fn to_eval_bars(bars: &[FixtureBar]) -> Vec<EvalBar> {
    bars.iter()
        .map(|bar| EvalBar {
            date: pack_date(&bar.date),
            open: bar.open,
            high: bar.high,
            low: bar.low,
            close: bar.close,
            volume: bar.volume,
        })
        .collect()
}

/// Builds a one-rule request around an expression so the production validator parses it.
fn parse_expression(expression: &Value) -> ExprV1 {
    let payload = serde_json::json!({
        "schemaVersion": 1,
        "requestedRunId": "ns01-parity",
        "universe": { "source": "activeNseEq" },
        "evaluation": { "evaluateHistory": false, "priceBasis": "raw" },
        "rules": [{ "id": "parity_rule", "expression": expression }]
    });
    let request = parse_native_scan_request_v1(&payload)
        .unwrap_or_else(|issues| panic!("fixture expression must validate: {issues:?}"));
    request.rules[0].expression.clone()
}

#[test]
fn ns01_fixture_bundle_is_the_expected_version() {
    let bundle = load_bundle();
    assert_eq!(bundle.contract_version, "eod-native-scan-contract-v1");
    assert_eq!(bundle.schema_version, 1);
    assert!(
        bundle.numeric_cases.len() >= 12,
        "numeric coverage too small"
    );
    assert!(
        bundle.contract_cases.len() >= 10,
        "contract coverage too small"
    );
    assert_eq!(bundle.bar_sets.len(), 3);
    for case in &bundle.numeric_cases {
        assert!(!case.id.trim().is_empty());
        assert!(!case.description.trim().is_empty());
        assert!(
            bundle.bar_sets.contains_key(&case.bar_set),
            "unknown bar set {} for {}",
            case.bar_set,
            case.id
        );
    }
}

#[test]
fn ns01_numeric_cases_match_recorded_typescript_values() {
    let bundle = load_bundle();
    for case in &bundle.numeric_cases {
        let expression = parse_expression(&case.expression);
        let bars = to_eval_bars(&bundle.bar_sets[&case.bar_set]);
        assert_eq!(
            bars.len(),
            case.expected_values.len(),
            "{}: bar count mismatch",
            case.id
        );
        let latest = evaluate_rule_latest(&expression, &bars)
            .unwrap_or_else(|error| panic!("{}: {error}", case.id));
        assert_eq!(
            latest.matched, case.expected_latest_matched,
            "{}: latest match mismatch",
            case.id
        );
        assert_eq!(
            minimum_bars_for_expression(&expression),
            case.minimum_bars,
            "{}: minimum bar accounting mismatch",
            case.id
        );

        // Compare each endpoint, which is also the historical-evaluation code path.
        for (index, expected) in case.expected_values.iter().enumerate() {
            let outcome = evaluate_rule_latest(&expression, &bars[..=index])
                .unwrap_or_else(|error| panic!("{}@{index}: {error}", case.id));
            let expected_matched = expected.map(|value| value != 0.0).unwrap_or(false);
            assert_eq!(
                outcome.matched, expected_matched,
                "{}@{index}: endpoint match mismatch (expected value {expected:?})",
                case.id
            );
        }
    }
}

#[test]
fn ns01_contract_cases_replay_the_typescript_decisions() {
    let bundle = load_bundle();
    for case in &bundle.contract_cases {
        let result = parse_native_scan_request_v1(&case.payload);
        match case.expect.as_str() {
            "ok" => {
                assert!(
                    result.is_ok(),
                    "{}: expected a valid request, got {:?}",
                    case.id,
                    result.err()
                );
                let request = result.expect("validated request");
                assert!(!request.rules.is_empty(), "{}", case.id);
                assert!(matches!(
                    request.evaluation.price_basis,
                    PriceBasisV1::Raw | PriceBasisV1::Adjusted
                ));
            }
            "error" => {
                let issues = result.expect_err(&format!("{}: expected rejection", case.id));
                let codes: Vec<&str> = issues.iter().map(|issue| issue.code.as_str()).collect();
                for expected in &case.expected_issue_codes {
                    assert!(
                        codes.contains(&expected.as_str()),
                        "{}: expected issue {expected}, got {codes:?}",
                        case.id
                    );
                }
                assert!(
                    issues.iter().all(|issue| !issue.path.is_empty()),
                    "{}: every issue needs a JSON path",
                    case.id
                );
            }
            other => panic!("{}: unknown expectation {other}", case.id),
        }
    }
}

#[test]
fn ns01_no_look_ahead_when_the_endpoint_moves_forward() {
    let bundle = load_bundle();
    let case = bundle
        .numeric_cases
        .iter()
        .find(|case| case.id == "numeric_close_above_sma20")
        .expect("baseline numeric case");
    let expression = parse_expression(&case.expression);
    let bars = to_eval_bars(&bundle.bar_sets[&case.bar_set]);

    // Evaluate every prefix; the final endpoint must agree with the full series result.
    let mut previous_matched: Option<bool> = None;
    for end in 1..=bars.len() {
        let outcome = evaluate_rule_latest(&expression, &bars[..end]).expect("evaluate prefix");
        if end == bars.len() {
            assert_eq!(outcome.matched, case.expected_latest_matched);
        }
        if end >= case.minimum_bars {
            previous_matched = Some(outcome.matched);
        } else {
            assert!(
                !outcome.matched,
                "endpoint {end} is inside the warm-up window and must not match"
            );
        }
    }
    assert!(previous_matched.is_some());
}
#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CoreMetadataFixture {
    version: u32,
    rules: BTreeMap<String, Value>,
    cases: Vec<CoreMetadataCase>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CoreMetadataCase {
    case_id: String,
    rule_id: String,
    description: String,
    symbol: String,
    exchange: String,
    bars: Vec<FixtureBar>,
    expected: Option<CoreMetadataExpected>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CoreMetadataExpected {
    symbol: String,
    exchange: String,
    scanner_id: String,
    scanner_name: String,
    category_id: String,
    category_name: String,
    date: String,
    matched: bool,
    direction: String,
    reasons: Vec<String>,
    values: BTreeMap<String, Value>,
    warnings: Vec<Value>,
    source: String,
}

/// Unlike the NS-01 boolean-only fixtures, this checks actual Rust core_match_record
/// against immutable rows that the real TypeScript runCoreScanner re-evaluates in
/// nativeCoreMetadataParityNSR3.test.ts. The generatedAt clock is intentionally omitted.
#[test]
fn nsr3_real_core_result_metadata_matches_typescript_fixtures() {
    use super::core_results::core_match_record;
    use super::reader::NativeBar;
    use super::scan::ScanTarget;
    use crate::scanner_contract::ScannerScalarValueV1;

    let fixture: CoreMetadataFixture = serde_json::from_str(include_str!(
        "../../../src/features/scanner/fixtures/nativeCoreMetadataParityFixtures.v1.json"
    ))
    .expect("shared NS-R3 metadata fixture must parse");
    assert_eq!(fixture.version, 1);
    assert_eq!(fixture.rules.len(), 10);
    assert!(fixture.cases.len() >= 40);
    for sample in &fixture.cases {
        assert!(!sample.description.is_empty(), "{}", sample.case_id);
        let expression = fixture
            .rules
            .get(&sample.rule_id)
            .unwrap_or_else(|| panic!("unknown core rule in {}", sample.case_id));
        let request = serde_json::json!({
            "schemaVersion": 1,
            "requestedRunId": "nsr3-parity",
            "universe": {"source": "activeNseEq"},
            "evaluation": {"evaluateHistory": false, "priceBasis": "raw"},
            "rules": [{"id": sample.rule_id, "expression": expression}]
        });
        let parsed = parse_native_scan_request_v1(&request)
            .unwrap_or_else(|issues| panic!("{} invalid AST: {issues:?}", sample.case_id));
        let rule = &parsed.rules[0];
        super::core_results::validate_core_rule(rule, false)
            .unwrap_or_else(|message| panic!("{}: {message}", sample.case_id));
        let eval_bars = to_eval_bars(&sample.bars);
        let evaluated = evaluate_rule_latest(&rule.expression, &eval_bars)
            .unwrap_or_else(|message| panic!("{}: {message}", sample.case_id));
        assert_eq!(
            evaluated.matched,
            sample.expected.is_some(),
            "{}: TypeScript/Rust predicate decision differs",
            sample.case_id
        );
        let Some(expected) = &sample.expected else {
            continue;
        };
        let bars: Vec<NativeBar> = sample
            .bars
            .iter()
            .map(|bar| NativeBar {
                date: pack_date(&bar.date),
                open: bar.open,
                high: bar.high,
                low: bar.low,
                close: bar.close,
                volume: bar.volume,
                prev_close: None,
                open_interest: 0.0,
            })
            .collect();
        let last_date = &sample.bars.last().expect("nonempty core fixture").date;
        let target = ScanTarget {
            exchange: sample.exchange.clone(),
            symbol: sample.symbol.clone(),
        };
        let actual = core_match_record(rule, &bars, &target, last_date, evaluated.value)
            .unwrap_or_else(|message| panic!("{}: {message}", sample.case_id))
            .unwrap_or_else(|| panic!("{} produced no Rust metadata", sample.case_id));
        assert_eq!(actual.symbol, expected.symbol, "{}", sample.case_id);
        assert_eq!(actual.exchange, expected.exchange, "{}", sample.case_id);
        assert_eq!(actual.rule_id, expected.scanner_id, "{}", sample.case_id);
        assert_eq!(actual.scanner_name.as_deref(), Some(expected.scanner_name.as_str()), "{}", sample.case_id);
        assert_eq!(actual.category_id.as_deref(), Some(expected.category_id.as_str()), "{}", sample.case_id);
        assert_eq!(actual.category_name.as_deref(), Some(expected.category_name.as_str()), "{}", sample.case_id);
        assert_eq!(actual.date, expected.date, "{}", sample.case_id);
        assert!(expected.matched, "{}", sample.case_id);
        assert_eq!(actual.direction.as_deref(), Some(expected.direction.as_str()), "{}", sample.case_id);
        assert_eq!(actual.reasons.as_deref(), Some(expected.reasons.as_slice()), "{}", sample.case_id);
        assert_eq!(actual.source.as_deref(), Some(expected.source.as_str()), "{}", sample.case_id);
        assert!(actual.score.is_none() && actual.pattern.is_none() && actual.history.is_none(), "{}", sample.case_id);
        // The TypeScript native result adapter adds warnings: [] to core rows.
        assert!(expected.warnings.is_empty(), "{}", sample.case_id);
        let actual_values = actual.values.as_ref().expect("core columns required");
        assert_eq!(actual_values.len(), expected.values.len(), "{}", sample.case_id);
        for (name, expected_value) in &expected.values {
            let actual_value = actual_values
                .get(name)
                .unwrap_or_else(|| panic!("{} missing column {name}", sample.case_id));
            if expected_value.is_null() {
                assert_eq!(actual_value, &ScannerScalarValueV1::Null, "{} {name}", sample.case_id);
                continue;
            }
            let expected_number = expected_value
                .as_f64()
                .unwrap_or_else(|| panic!("{} column {name} not numeric", sample.case_id));
            let actual_number = match actual_value {
                ScannerScalarValueV1::Integer(integer) => *integer as f64,
                ScannerScalarValueV1::Float(float) => *float,
                _ => panic!("{} unexpected type for {name}", sample.case_id),
            };
            assert_eq!(actual_number, expected_number, "{} {name}", sample.case_id);
        }
    }
}
